SELECT COUNT(*) AS bad_rows
FROM orders
WHERE Revenue <= 0 OR ShippingDays < 0;

SELECT p.ProductName, p.Category, p.SellingPrice
FROM products p
WHERE p.SellingPrice > (
  SELECT AVG(p2.SellingPrice) FROM products p2 WHERE p2.Category = p.Category
)
ORDER BY p.Category, p.SellingPrice DESC;

SELECT COUNT(DISTINCT CustomerID) AS customers_with_a_return
FROM orders
WHERE ReturnFlag = 'Yes';

SELECT *
FROM customers
QUALIFY ROW_NUMBER() OVER (PARTITION BY CustomerID ORDER BY JoinDate DESC) = 1;
